#[cfg(test)] mod tests{
    use super::*;
    #[test]
    fn all_controller_instructions_and_literal_jump_table_are_adjacent(){
        let f=fragment();
        assert_eq!(f.code.len(),INSTRUCTION_COUNT+1);
        let data=super::super::extension6_disjoint::emit(&f).unwrap();
        assert_eq!(data.len(),FILE_END-FILE_START);
        assert_eq!(data[0..4],[0x42,0x12,0x80,0x03]); // ABS r1,r5
        assert_eq!(data[FILE_END-FILE_START-28..].len(),28);
        assert_eq!(CONTROLLER_DISPATCH14.len(),14);
        for target in CONTROLLER_DISPATCH14 {
            assert_eq!(target&1,0);
            assert!((0x8c44..0x8e62).contains(&target));
        }
    }
}
